import { wrapWithContext } from "../../errors/index.js";
import { SpanNames } from "../../observability/index.js";
import { withSpan } from "../../observability/tracing/otlp-setup.js";
import { Singleflight } from "../../utils/singleflight.js";
import { isAbsolute, join } from "../../platform/compat/path/index.js";
// Module-level so dedup spans compiler instances: the renderer creates an
// MDXCompiler per render context, and the bundle cache key (mdx:<mode>:<hash>)
// is already global, so the flight map can be too.
const compileFlight = new Singleflight();
export class MDXCompiler {
    config;
    constructor(config) {
        this.config = config;
    }
    compileMDX(content, frontmatter, filePath) {
        const spanAttrs = {
            "mdx.file_path": filePath ?? "inline",
            "mdx.content_length": content.length,
        };
        return withSpan(SpanNames.MDX_COMPILE, async () => {
            const cachedBundle = await withSpan(SpanNames.MDX_CACHE_GET, () => this.config.mdxCacheAdapter.getCachedBundle(content, frontmatter, filePath), spanAttrs);
            if (cachedBundle)
                return cachedBundle;
            // Key includes projectDir and filePath because relative imports are
            // resolved against the file's location: identical source in two
            // places can compile to different modules, so only compiles of the
            // same file may share an in-flight promise.
            const contentHash = await this.config.mdxCacheAdapter.computeHash(content);
            const flightKey = `mdx:${this.config.projectDir}:${this.config.mode}:${contentHash}:${filePath ?? "inline"}`;
            return compileFlight.do(flightKey, () => this.compileAndCache(content, frontmatter, filePath));
        }, { ...spanAttrs, "mdx.mode": this.config.mode }).then((bundle) => filePath === undefined ? bundle : {
            ...bundle,
            sourcePath: isAbsolute(filePath) ? filePath : join(this.config.projectDir, filePath),
        });
    }
    async compileAndCache(content, frontmatter, filePath) {
        const { compileContent } = await import("../../transforms/mdx/compiler/index.js");
        try {
            const bundle = (await compileContent(this.config.mode, this.config.projectDir, content, frontmatter, filePath, "server"));
            await withSpan(SpanNames.MDX_CACHE_SET, () => this.config.mdxCacheAdapter.setCachedBundle(content, bundle, filePath), { "mdx.file_path": filePath ?? "inline" });
            return bundle;
        }
        catch (error) {
            throw wrapWithContext(error, "MDX compilation failed", { filePath });
        }
    }
}
